func TestIsAgentSubprocess_GitTerminalPromptZero(t *testing.T) {
	t.Setenv("GIT_TERMINAL_PROMPT", "0")
	if !isAgentSubprocess() {
		t.Error("isAgentSubprocess() = false; want true when GIT_TERMINAL_PROMPT=0")
